# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NİSÂ SURESİ 58-101. AYETLERİN TEMEL İLKELERİ VE HÜKÜMLERİ</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Emanet ve Adalet (58-59)</text>\n  <text x="30" y="98" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Emaneti Ehline Verme:</text>\n  <text x="38" y="114" font-size="10" fill="#334155">Görev ve sorumlulukta liyakat</text>\n  <text x="38" y="128" font-size="10" fill="#334155">ve ehliyet esasının gözetilmesi.</text>\n  <text x="30" y="152" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Adaletle Hükmetme:</text>\n  <text x="38" y="168" font-size="10" fill="#334155">İnsanlar arasında tarafsız ve</text>\n  <text x="38" y="182" font-size="10" fill="#334155">hakkaniyetli karar verilmesi.</text>\n  <text x="30" y="206" font-size="10" font-weight="bold" fill="#1e40af">• Kur\'an ve Sünnet Hakemliği</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Selam ve Barış (86-94)</text>\n  <text x="255" y="98" font-size="10.5" font-weight="bold" fill="#166534">• Selamlaşma Âdâbı (86):</text>\n  <text x="263" y="114" font-size="10" fill="#334155">Verilen selama daha güzeliyle</text>\n  <text x="263" y="128" font-size="10" fill="#334155">veya misliyle karşılık verme.</text>\n  <text x="255" y="152" font-size="10.5" font-weight="bold" fill="#166534">• Can Dokunulmazlığı (92-93):</text>\n  <text x="263" y="168" font-size="10" fill="#334155">Müminin canına kastetmenin</text>\n  <text x="263" y="182" font-size="10" fill="#334155">büyük günah oluşu; hataen</text>\n  <text x="263" y="196" font-size="10" fill="#334155">öldürmede diyet ve kefaret.</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Sefer ve Korku Namazı</text>\n  <text x="480" y="98" font-size="10.5" font-weight="bold" fill="#b45309">• Kasr-ı Salât (101. Ayet):</text>\n  <text x="488" y="114" font-size="10" fill="#334155">Yolculukta (seferîlikte) dört</text>\n  <text x="488" y="128" font-size="10" fill="#334155">rekâtlı farz namazların iki</text>\n  <text x="488" y="142" font-size="10" fill="#334155">rekât olarak kısaltılması.</text>\n  <text x="480" y="168" font-size="10.5" font-weight="bold" fill="#b45309">• Salât-ı Havf (102. Ayet):</text>\n  <text x="488" y="184" font-size="10" fill="#334155">Savaş ve tehlike anında dahi</text>\n  <text x="488" y="198" font-size="10" fill="#334155">namazın nöbetleşe kılınması.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FUSSİLET SURESİ (1-25. AYETLER) KİMLİK BİLGİSİ VE ANA KONULARI</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Fussilet Suresi Tanıtım Kartı</text>\n  <text x="40" y="102" font-size="11" fill="#4c1d95">• İniş Dönemi ve Yeri: Mekke Dönemi (Mekkî)</text>\n  <text x="40" y="124" font-size="11" fill="#4c1d95">• Ayet Sayısı ve Cüz: 54 Ayet (24-25. Cüz)</text>\n  <text x="40" y="146" font-size="11" fill="#4c1d95">• Adının Anlamı: \'Ayrıntılı olarak açıklandı\'</text>\n  <text x="40" y="168" font-size="11" fill="#4c1d95">• Diğer Adı: Hâ-Mîm es-Secde Suresi</text>\n  <text x="40" y="190" font-size="11" font-weight="bold" fill="#6d28d9">• Başlangıç: Hâ-Mîm (Hurûf-ı Mukattaa)</text>\n  <text x="40" y="212" font-size="11" font-weight="bold" fill="#6d28d9">• 37. Ayet: Tilavet Secdesi Ayeti</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">1-25. Ayetlerin Temel Mesajları</text>\n  <text x="380" y="102" font-size="10.5" fill="#075985">• Kur\'an\'ın Rahmân ve Rahîm olan Allah\'tan</text>\n  <text x="388" y="118" font-size="10.5" fill="#334155">indirilen müjdeleyici ve uyarıcı vahiy oluşu.</text>\n  <text x="380" y="142" font-size="10.5" fill="#075985">• Yerin, dağların, rızıkların ve duman (duhân)</text>\n  <text x="388" y="158" font-size="10.5" fill="#334155">hâlindeki yedi göğün yaratılış düzeni.</text>\n  <text x="380" y="182" font-size="10.5" fill="#075985">• Âd ve Semûd kavimlerinin kibir ve inkâr</text>\n  <text x="388" y="198" font-size="10.5" fill="#334155">yüzünden uğradıkları helak.</text>\n  <text x="380" y="220" font-size="10.5" font-weight="bold" fill="#0369a1">• Ahirette kulak, göz ve derilerin şahitliği.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NİSÂ VE FUSSİLET SURELERİNDEN UYGULAMALI TECVİT ÖRNEKLERİ</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. Med Kuralları</text>\n  <text x="30" y="98" font-size="10.5" font-weight="bold" fill="#b45309">• حمٓ (Hâ - Mîm):</text>\n  <text x="38" y="114" font-size="10" fill="#334155">\'Mîm\' harfinde sükûn-ı lâzım</text>\n  <text x="38" y="128" font-size="10" fill="#334155">sebebiyle Medd-i Lâzım (4 elif).</text>\n  <text x="30" y="152" font-size="10.5" font-weight="bold" fill="#b45309">• سَوَآءً (Sevâen):</text>\n  <text x="38" y="168" font-size="10" fill="#334155">Aynı kelimede med harfi +</text>\n  <text x="38" y="182" font-size="10" fill="#334155">hemze -&gt; Medd-i Muttasıl.</text>\n  <text x="30" y="206" font-size="10.5" font-weight="bold" fill="#b45309">• بَص۪يرًا -&gt; بَص۪يرَا (Vakıf):</text>\n  <text x="38" y="222" font-size="10" fill="#334155">İki üstünde duruş -&gt; Medd-i İvaz.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Sakin Nun ve Tenvin</text>\n  <text x="255" y="98" font-size="10.5" font-weight="bold" fill="#166534">• تَنْز۪يلٌ / أَنْ تَحْكُمُوا:</text>\n  <text x="263" y="114" font-size="10" fill="#334155">Sakin nun + ز / ت -&gt; İhfâ.</text>\n  <text x="255" y="138" font-size="10.5" font-weight="bold" fill="#166534">• تَنْز۪يلٌ مِنَ / قُرْاٰنًا عَرَبِيًّا:</text>\n  <text x="263" y="154" font-size="10" fill="#334155">Tenvin + م -&gt; İdgam-ı Maal-Gunne;</text>\n  <text x="263" y="168" font-size="10" fill="#334155">Tenvin + ع -&gt; İzhar.</text>\n  <text x="255" y="192" font-size="10.5" font-weight="bold" fill="#166534">• سَم۪يعًا بَص۪يرًا (Semî\'an basîrâ):</text>\n  <text x="263" y="208" font-size="10" fill="#334155">Tenvin + ب -&gt; İklab (Mîm\'e dönüşür).</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">3. İdgam ve Mahreç</text>\n  <text x="480" y="98" font-size="10.5" font-weight="bold" fill="#1d4ed8">• فُصِّلَتْ (Fussilet):</text>\n  <text x="488" y="114" font-size="10" fill="#334155">Sâd (ص) kalın ve ıslıklı harf;</text>\n  <text x="488" y="128" font-size="10" fill="#334155">sondaki cezimli ت\'de hems sesi.</text>\n  <text x="480" y="152" font-size="10.5" font-weight="bold" fill="#1d4ed8">• اَلرَّحْمٰنِ الرَّح۪يمِ:</text>\n  <text x="488" y="168" font-size="10" fill="#334155">Elif-lam + ر -&gt; İdgam-ı Şemsiyye</text>\n  <text x="488" y="182" font-size="10" fill="#334155">ve Râ harfi kalın okunur.</text>\n  <text x="480" y="206" font-size="10.5" font-weight="bold" fill="#1d4ed8">• قَدْ / خَلَقَ: Kalkale harfleri.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
